  /**
   * @method
   * @name zebpay#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see [Spot]
   * https://github.com/zebpay/zebpay-api-references/blob/main/spot/api-reference/public-endpoints.md#system-status
   * @see [Swap]
   * https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/public-endpoints/system.md#get-system-status
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<ccxt::any>
  fetchStatus(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any type = ccxt::any{};
                 ccxt::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchStatus"), ccxt::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 ccxt::any isSpot = (isEqual(type, std::string("spot")));
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::dict{};
                 if (isTrue(isSpot)) {
                   response =
                       awaitValue(this->publicSpotGetV2SystemStatus(params));
                   data = response;
                 } else {
                   response =
                       awaitValue(this->publicSwapGetV1SystemStatus(params));
                   data = this->safeDict(response, std::string("data"),
                                         ccxt::dict{});
                 }
                 //
                 // {
                 //     "statusDescription": "OK",
                 //     "data":
                 //      {
                 //        "systemStatus": "ok"
                 //       }
                 //     "statusCode": 200,
                 //     "customMessage": ["OK"]
                 // }
                 //
                 ccxt::any status = this->safeString2(
                     data, std::string("systemStatus"), std::string("status"));
                 return ccxt::dict{
                     {std::string("status"), status},
                     {std::string("updated"), ccxt::any{}},
                     {std::string("eta"), ccxt::any{}},
                     {std::string("url"), ccxt::any{}},
                     {std::string("info"), response},
                 };
               })
        .share();
  }

