  /**
   * @method
   * @name zebpay#setLeverage
   * @description set the level of leverage for a market
   * @see [Swap]
   * https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/private-endpoints/trade.md#-update-user-leverage
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<ccxt::any>
  setLeverage(ccxt::any leverage, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("leverage"), leverage},
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 //
                 // { data: { "symbol", "longLeverage": 10, "shortLeverage": 1,
                 // "marginMode": "isolated" }
                 //
                 ccxt::any response =
                     awaitValue(this->privateSwapPostV1TradeUpdateUserLeverage(
                         this->extend(request, params)));
                 return response;
               })
        .share();
  }

