  virtual std::shared_future<ccxt::any>
  fetchSpotMarkets(ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any response =
                     awaitValue(this->publicSpotGetV2ExExchangeInfo(params));
                 //
                 //    {
                 //        "data": {
                 //            "symbol": "ETH-INR",
                 //            "name": "ETH-INR",
                 //            "baseCurrency": "ETH",
                 //            "quoteCurrency": "INR",
                 //            "feeCurrency": "INR",
                 //            "baseMinSize": "",
                 //            "quoteMinSize": "100",
                 //            "baseMaxSize": "",
                 //            "quoteMaxSize": "2000",
                 //            "baseIncrement": "0.00001"
                 //            "quoteIncrement": "0.00001",
                 //            "enableTrading": true
                 //        }
                 //    }
                 //
                 ccxt::any result = ccxt::list{};
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any markets =
                     this->safeList(data, std::string("symbols"), ccxt::list{});
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(markets));
                      postFixIncrement(i)) {
                   ccxt::any market = ::getValue(markets, i);
                   ccxt::any id =
                       this->safeString(market, std::string("symbol"));
                   ccxt::any baseId =
                       this->safeString(market, std::string("baseAsset"));
                   ccxt::any quoteId =
                       this->safeString(market, std::string("quoteAsset"));
                   ccxt::any base = this->safeCurrencyCode(baseId);
                   ccxt::any quote = this->safeCurrencyCode(quoteId);
                   ccxt::any symbol = add(add(base, std::string("/")), quote);
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("symbol"), symbol},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("type"), std::string("spot")},
                           {std::string("spot"), true},
                           {std::string("swap"), false},
                           {std::string("margin"), false},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"), ccxt::any{}},
                           {std::string("contract"), ccxt::any{}},
                           {std::string("taker"),
                            this->safeNumber(market, std::string("takerFee"))},
                           {std::string("maker"),
                            this->safeNumber(market, std::string("makerFee"))},
                           {std::string("strike"), ccxt::any{}},
                           {std::string("optionType"), ccxt::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->safeNumber(market,
                                                  std::string("lotSz"))},
                                {std::string("price"),
                                 this->safeNumber(market,
                                                  std::string("tickSz"))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                            }},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

